import { GoogleGenAI, Part } from "@google/genai";
import { EventFormData } from "../types";

// Helper to convert File to Part
export const fileToPart = async (file: File): Promise<Part> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      // Check if result is string
      if (typeof reader.result === 'string') {
        // Fallback to jpeg if file.type is empty (common with some file objects)
        const mimeType = file.type || 'image/jpeg';
        const base64String = reader.result.split(',')[1];
        resolve({
          inlineData: {
            data: base64String,
            mimeType: mimeType,
          },
        });
      } else {
        reject(new Error("Failed to read file"));
      }
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const base64ToPart = (base64: string, mimeType: string = 'image/png'): Part => {
    // Ensure we strip any Data URL prefix correctly.
    // Handles data:image/png;base64, and similar patterns.
    const data = base64.replace(/^data:image\/[a-zA-Z]+;base64,/, "");
    return {
        inlineData: {
            data,
            mimeType
        }
    };
};

// Helper to fetch default MISA Logo
const getDefaultMisaLogoPart = async (): Promise<Part | null> => {
    const urls = [
        'https://www.misa.vn/wp-content/uploads/2025/12/logo_MISA_transparent_background-scaled.png', // Priority: User Requested Logo
        'https://misa.vn/wp-content/uploads/2020/10/logo-misa.png', 
        'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/MISA_logo.svg/500px-MISA_logo.svg.png'
    ];

    for (const url of urls) {
        try {
            const response = await fetch(url); 
            if (response.ok) {
                const blob = await response.blob();
                return new Promise((resolve) => {
                     const reader = new FileReader();
                     reader.onloadend = () => {
                         if (typeof reader.result === 'string') {
                            const base64 = reader.result.split(',')[1];
                            resolve({ inlineData: { data: base64, mimeType: 'image/png' } });
                         } else {
                             resolve(null);
                         }
                     };
                     reader.readAsDataURL(blob);
                });
            }
        } catch (e) {
            console.warn(`Failed to fetch MISA logo from ${url}`, e);
        }
    }
    return null;
}

/**
 * Extracts event information from a document or image using Gemini 2.5 Flash.
 */
export const extractEventInfo = async (file: File): Promise<Partial<EventFormData>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const filePart = await fileToPart(file);

  // Vietnamese Prompt for better local context extraction
  const prompt = `
    Bạn là một trợ lý AI chuyên trích xuất thông tin sự kiện từ các tài liệu hoặc hình ảnh thư mời.
    Hãy phân tích file đính kèm và trích xuất các thông tin sau dưới dạng JSON:

    - eventName: Tên sự kiện (Tiêu đề chính).
    - eventType: Loại sự kiện (Hội thảo, Tập huấn, Lễ ra mắt...).
    - date: Ngày diễn ra (Định dạng DD/MM/YYYY).
    - time: Giờ diễn ra (Ví dụ: 08:00 - 11:30).
    - targetAudience: Đối tượng khách mời tham gia.
    - isOnline: true nếu là Zoom/Google Meet/Online, false nếu là Offline.
    - locationOrPlatform: Địa điểm tổ chức hoặc link Zoom/ID Zoom.
    - dressCode: Thông tin về trang phục (nếu có).
    - contactName: Tên người liên hệ.
    - contactPhone: Số điện thoại liên hệ.
    - contactEmail: Email liên hệ.

    Nếu không tìm thấy thông tin nào, hãy để chuỗi rỗng "". 
    Đừng tự bịa thông tin.
    Trả về định dạng JSON thuần túy, không markdown.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [filePart, { text: prompt }],
      },
      config: {
        responseMimeType: 'application/json',
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);

    return {
      eventType: data.eventType || '',
      eventName: data.eventName || '',
      date: data.date || '',
      time: data.time || '',
      targetAudience: data.targetAudience || '',
      isOnline: typeof data.isOnline === 'boolean' ? data.isOnline : false,
      locationOrPlatform: data.locationOrPlatform || '',
      dressCode: data.dressCode || '',
      contactName: data.contactName || '',
      contactPhone: data.contactPhone || '',
      contactEmail: data.contactEmail || '',
    };
  } catch (error) {
    console.error("Extraction failed", error);
    throw new Error("Failed to extract information from file.");
  }
};

/**
 * Generates a clean background from an uploaded image (removes text/logos).
 */
export const cleanBackground = async (imageFile: File): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const imagePart = await fileToPart(imageFile);

    const prompt = `
        I provide an event poster or design.
        Please recreate the **BACKGROUND ONLY** of this image.
        1. Keep the abstract shapes, colors, gradients, and layout style exactly as they are.
        2. REMOVE ALL TEXT, LOGOS, PEOPLE, and FOREGROUND OBJECTS.
        3. The output should be a clean, high-quality background texture ready for new text to be overlaid.
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image', // Using Flash Image for fast editing/recreation
            contents: { parts: [imagePart, { text: prompt }] }
        });

         // Extract the image from the response
        for (const part of response.candidates?.[0]?.content?.parts || []) {
            if (part.inlineData) {
                return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            }
        }
        throw new Error("No image generated.");
    } catch (error) {
        console.error("Clean background failed", error);
        throw new Error("Không thể xử lý nền ảnh. Vui lòng thử lại.");
    }
}

/**
 * Generates the event poster using Gemini 3 Pro Image Preview (Nano Banana Pro).
 */
export const generatePoster = async (formData: EventFormData): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: Part[] = [];

  // Determine effective topics (mix)
  const topics = formData.themeTopics.includes('Tùy chỉnh') 
    ? formData.customTopicPrompt 
    : formData.themeTopics.join(' combined with ');

  // 1. Construct the System/Layout Prompt
  let prompt = `Create a high-quality, professional event invitation poster for MISA (Vietnam).

  **Format & Size:**
  - Aspect Ratio: ${formData.aspectRatio === '16:9' ? 'Landscape (16:9)' : 'Portrait (3:4)'}.
  - Output Resolution: High Quality.

  **Design Style & Theme:**
  - **Color Palette:** ${formData.themeTone} ${formData.customThemePrompt ? `(${formData.customThemePrompt})` : ''}.
  - **Topic/Theme:** ${topics}.
  - **Vibe:** Professional, Modern, Corporate, Reliable.

  **LANGUAGE SETTING:**
  - **IMPORTANT:** ALL TEXT ON THE POSTER MUST BE IN **VIETNAMESE**.
  `;

  // Handle User Selected Background / Template
  if (formData.useUploadedBackground && formData.selectedBackground) {
      if (formData.selectedBackground.startsWith('data:image')) {
          parts.push(base64ToPart(formData.selectedBackground));
          prompt += `\n\n**BACKGROUND INSTRUCTION:**
          - Use the provided image (Image ${parts.length}) as the **STRICT BACKGROUND REFERENCE**.
          - Keep the background patterns, colors, and layout structure of this reference image.
          - Place the new text and content on top of this background style.
          `;
      }
  }

  prompt += `
  **Content to Render (Must be legible and accurate):**

  - **Event Type:** "${formData.eventType}".
    - **Placement:** Positioned DIRECTLY ABOVE the Event Title.
    - **Style:** Elegant, readable.

  - **Event Title:** "${formData.eventName}".
    - **Visual Importance:** MOST PROMINENT element.
    - **Typography:** Bold, 3D or creative display fonts. High contrast.

  - **Time & Date:**
    - **ICON:** Draw a **CLOCK or CALENDAR ICON** to the left of the text.
    - **Text:** "${formData.time} | ${formData.date}" (Large, Clear).
  `;

  // Location / Format Logic
  if (formData.isOnline) {
      prompt += `
      - **Format/Location Line:**
        - **Text Content:** "Hình thức: Zoom online" (Write exactly this Vietnamese phrase).
        - **Icon:** Optional Zoom icon or just text.
        - **Placement:** Below Time & Date.
      `;
  } else {
      prompt += `
      - **Format/Location Line:**
        - **ICON:** Draw a distinct **LOCATION PIN ICON** (Map marker).
        - **Text Content:** "${formData.locationOrPlatform}"
        - **Placement:** Next to the icon, Below Time & Date.
      `;
  }

  // --- AGENDA SECTION ---
  if (formData.agenda && formData.agenda.length > 0) {
      prompt += `\n\n**PROGRAM AGENDA ("CHƯƠNG TRÌNH"):**
      - Title: "CHƯƠNG TRÌNH" (or "AGENDA").
      - Use a clear list layout.
      - Content:
      `;
      formData.agenda.forEach(item => {
          prompt += `  - ${item.time} : ${item.activity}\n`;
      });
  }

  // --- DRESSCODE SECTION (Below Agenda) ---
  if (formData.dressCode) {
      prompt += `\n- **Dresscode Info:**
      - **Text:** "Trang phục: ${formData.dressCode}"
      - **Placement:** Render BELOW the agenda/program list.
      - **Style:** Normal, clean font (not bold, not too small).
      `;
  }

  prompt += `
  - **Target Audience:** "${formData.targetAudience}".
  `;

  // --- CONTACT SECTION LOGIC ---
  const hasContactInfo = formData.contactName || formData.contactPhone || formData.contactEmail;
  if (hasContactInfo) {
      // Normal behavior: Render the text
      const contactString = [formData.contactName, formData.contactPhone, formData.contactEmail].filter(Boolean).join(' - ');
      prompt += `\n- **Contact Info:** "${contactString}" (Place at bottom footer).`;
  } else {
      // Empty behavior: Draw placeholder box
      prompt += `\n- **Contact Info:** Draw a **LONG EMPTY WHITE RECTANGULAR BOX** at the bottom/footer area.
      - **CRITICAL:** Do NOT write any text inside this box. It must be empty for handwriting.
      - **ICON:** Place a **PHONE ICON** inside or immediately next to this white box.
      - Do NOT write the word "Contact" or "Liên hệ". Just the icon and the empty white box.`;
  }

  // --- MISA LOGO SETUP (MANDATORY) ---
  const misaLogoPart = await getDefaultMisaLogoPart();
  let misaLogoRef = "";
  if (misaLogoPart) {
      parts.push(misaLogoPart);
      misaLogoRef = `Image ${parts.length}`;
  }

  prompt += `\n\n**LOGOS & BRANDING INSTRUCTIONS:**`;

  if (formData.useBrandLogo) {
      // === CASE 1: CUSTOM BRANDING ENABLED ===
      // Requirement: MISA Logo MUST be at the OUTER LEFT (Top Left), other logos follow.
      // Requirement: MISA Logo MUST be on WHITE BACKGROUND.

      if (misaLogoRef) {
          prompt += `\n- **Organizer Logo (MISA)**: See ${misaLogoRef}. 
          - **POSITION:** **TOP LEFT** (The absolute left-most logo).
          - **IMPORTANT STYLE:** This logo MUST be placed on a **SOLID WHITE RECTANGULAR BACKGROUND BOX**. The white box ensures the logo is legible on any background color.`;
      } else {
          prompt += `\n- **MISA Logo**: Draw "MISA" text in Blue at **TOP LEFT** on a **WHITE BACKGROUND**.`;
      }

      // 1. Co-Organizer (User uploaded "Organizer Logo" slot acts as secondary organizer here)
      if (formData.organizerLogo) {
          parts.push(await fileToPart(formData.organizerLogo));
          prompt += `\n- **Co-Organizer Logo**: See Image ${parts.length}. Position: **TOP CENTER-LEFT** (To the immediate RIGHT of the MISA logo).`;
      }

      // 2. Partner Products ("Sản phẩm đồng hành")
      if (formData.productLogo) {
        parts.push(await fileToPart(formData.productLogo));
        prompt += `\n- **Partner Product**: See Image ${parts.length}. Label "Sản phẩm đồng hành" above/below it. Position: Separate group or Top Right area.`;
      }
      // 3. Co-Partners ("Đơn vị phối hợp")
      if (formData.coOrganizerLogo) {
        parts.push(await fileToPart(formData.coOrganizerLogo));
        prompt += `\n- **Other Partners**: See Image ${parts.length}. Label "Đơn vị phối hợp" above/below it. Position: Bottom logos or Far Right.`;
      }

  } else {
      // === CASE 2: DEFAULT (NO BRANDING) ===
      // Requirement: MISA Logo at TOP CENTER.
      // Requirement: MISA Logo MUST be on WHITE BACKGROUND.

      if (misaLogoRef) {
          prompt += `\n- **Main Organizer Logo (MISA)**: See ${misaLogoRef}. 
          - **POSITION:** **TOP CENTER** (Main Hero Position).
          - **IMPORTANT STYLE:** This logo MUST be placed on a **SOLID WHITE RECTANGULAR BACKGROUND BOX**. The white box ensures the logo is legible on any background color.`;
      } else {
          prompt += `\n- **MISA Logo**: Draw "MISA" text in Blue at **TOP CENTER** on a **WHITE BACKGROUND**.`;
      }
  }

  // Explicit Slogan Instruction for MISA
  prompt += `\n**IMPORTANT:** For the MISA Logo, ensure the slogan "TIN CẬY - TIỆN ÍCH - TẬN TÌNH" is included below the logo text if resolution permits.`;

  // --- QR CODE ---
  if (formData.includeQrCode) {
      const qrCtaText = formData.qrCta || "Đăng ký ngay";
      if (formData.qrCodeImage) {
          parts.push(await fileToPart(formData.qrCodeImage));
          prompt += `\n\n**QR Code:** See Image ${parts.length}. Place at bottom/corner with text "${qrCtaText}".`;
      } else {
          prompt += `\n\n**QR Code Placeholder:** Draw a SOLID WHITE SQUARE BOX (Empty) with text "${qrCtaText}" below it.`;
      }
  }

  prompt += `\n\n**Speakers (DIỄN GIẢ):**`;
  // Speakers Logic
  for (let i = 0; i < formData.speakers.length; i++) {
    const speaker = formData.speakers[i];
    prompt += `\n- Speaker ${i + 1}:
    **CRITICAL RENDER INSTRUCTION: YOU MUST DISPLAY 3 DISTINCT LINES OF TEXT BELOW THE PHOTO:**
    1. **Name:** "${speaker.name}" (Bold/Prominent)
    2. **Title:** "${speaker.title}" (Smaller)
    3. **Company:** "${speaker.company}" (Smallest/Italic)`;

    if (speaker.image) {
      parts.push(await fileToPart(speaker.image));
      prompt += ` [Ref: Image ${parts.length}]`;

      // NEW: Enhanced "Vest" Logic
      if (speaker.editPrompt) {
          // Replace "vest" with "Professional Business Suit" to avoid "waistcoat" interpretation
          // "gi" flag for global case-insensitive replacement
          let safePrompt = speaker.editPrompt.replace(/vest/gi, "Professional Business Suit (Long-sleeve Blazer)");

          prompt += `
          **EDIT INSTRUCTION:** ${safePrompt}.
          **ATTIRE RULES:**
          - If the user requested a suit/vest: Generate a **PROFESSIONAL BUSINESS SUIT** (Jacket/Blazer + Shirt).
          - **MUST HAVE LONG SLEEVES**.
          - **NO** Waistcoats (Gile). **NO** Sleeveless vests. **NO** Waiter/Server uniforms.
          - Vibe: Corporate Executive, Speaker, Leader.
          `;
      }

      if (speaker.removeBackground) prompt += ` Remove background.`;
    } else {
        prompt += ` (Generate professional avatar).`;
    }
  }

  // Add the text prompt as the last part
  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts
      },
      config: {
        imageConfig: {
            aspectRatio: formData.aspectRatio,
            imageSize: '2K'
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image generated.");

  } catch (error) {
    console.error("Poster Generation Failed", error);
    const msg = (error as any).message || "Unknown Error";
    throw new Error(`Poster Generation Failed: ${msg}`);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { INITIAL_FORM_DATA, EventFormData, AppMode, AspectRatio, Speaker, HistoryItem } from './types';
import { generatePoster, extractEventInfo } from './services/geminiService';
import Header from './components/Header';
import SpeakerSection from './components/SpeakerSection';
import LogoSection from './components/LogoSection';
import AgendaSection from './components/AgendaSection';
import TemplateLibrary from './components/TemplateLibrary';
import { 
  Layout, Palette, CheckCircle2, Download, ZoomIn, Loader2, 
  FileText, UploadCloud, RefreshCw, Sparkles, ImagePlus, 
  QrCode, Trash2, CalendarClock, MapPin, Target, Upload, 
  Maximize2, X, ChevronRight, Wand2, History, ImageIcon, Play,
  MoreVertical, Calendar, Shirt, Users
} from 'lucide-react';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>('manual');
  const [formData, setFormData] = useState<EventFormData>(INITIAL_FORM_DATA);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isExtracting, setIsExtracting] = useState(false);
  const [isExtracted, setIsExtracted] = useState(false); // Track if extraction happened in Auto mode
  const [previewOpen, setPreviewOpen] = useState(false);

  // Ref for auto-scrolling to result
  const resultRef = useRef<HTMLDivElement>(null);

  const THEMES = [
    { value: 'Xanh công nghệ (MISA Blue)', label: 'Xanh công nghệ (MISA Blue)' },
    { value: 'Đen huyền bí (Black & Gold)', label: 'Đen huyền bí (Black & Gold)' },
    { value: 'Xanh Navy - Trắng (Corporate)', label: 'Xanh Navy - Trắng (Corporate)' },
    { value: 'Đỏ - Trắng - Đen (Energetic)', label: 'Đỏ - Trắng - Đen (Energetic)' },
    { value: 'Xanh - Trắng - Đen (Modern)', label: 'Xanh - Trắng - Đen (Modern)' },
    { value: 'Tùy chỉnh', label: 'Tùy chỉnh...' }
  ];

  const TOPICS = [
    'Tài chính - Kế toán', 'Công nghệ', 'AI', 'Bán hàng', 
    'Marketing', 'Nhân sự', 'Điều hành', 'Sản xuất', 'Tùy chỉnh'
  ];

  const updateFormData = (updates: Partial<EventFormData>) => {
    setFormData(prev => ({ ...prev, ...updates }));
  };

  const handleTopicToggle = (topic: string) => {
    setFormData(prev => {
      let newTopics = [...prev.themeTopics];

      if (topic === 'Tùy chỉnh') {
        if (newTopics.includes('Tùy chỉnh')) {
          newTopics = newTopics.filter(t => t !== 'Tùy chỉnh');
        } else {
           if (newTopics.length >= 2) newTopics.shift();
           newTopics.push('Tùy chỉnh');
        }
      } else {
        if (newTopics.includes(topic)) {
          newTopics = newTopics.filter(t => t !== topic);
        } else {
          if (newTopics.length >= 2) newTopics.shift();
          newTopics.push(topic);
        }
      }
      return { ...prev, themeTopics: newTopics };
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Preview if image
    let previewUrl = undefined;
    if (file.type.startsWith('image/')) {
        previewUrl = URL.createObjectURL(file);
    }

    // Save file to state but DO NOT extract yet
    updateFormData({
        uploadedFileName: file.name,
        uploadedFileType: file.type,
        uploadedFilePreview: previewUrl,
        uploadedFile: file
    });
    setIsExtracted(false); // Reset extraction state on new file
  };

  const handleExtractInfo = async () => {
    if (!formData.uploadedFile) return;

    setIsExtracting(true);
    try {
      const extractedData = await extractEventInfo(formData.uploadedFile);
      updateFormData(extractedData);
      setIsExtracted(true); // Reveal fields
    } catch (error) {
      console.error(error);
      alert('Không thể trích xuất thông tin. Vui lòng thử lại hoặc nhập thủ công.');
    } finally {
      setIsExtracting(false);
    }
  };

  const handleQrUpload = (file: File) => {
    const reader = new FileReader();
    reader.onload = () => updateFormData({ qrCodeImage: file, qrCodePreview: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      const result = await generatePoster(formData);
      setGeneratedImage(result);

      // Add to history
      const newHistoryItem: HistoryItem = {
          id: crypto.randomUUID(),
          image: result,
          createdAt: Date.now()
      };
      setHistory(prev => [newHistoryItem, ...prev]);

      // Auto switch view or scroll
      if (window.innerWidth < 1024) {
          setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
      }
    } catch (error) {
      alert((error as Error).message);
    } finally {
      setIsGenerating(false);
    }
  };

  const openHistoryItem = (img: string) => {
      setGeneratedImage(img);
      setPreviewOpen(true);
  };

  const deleteHistoryItem = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (window.confirm('Bạn có chắc chắn muốn xóa thiết kế này không?')) {
          setHistory(prev => prev.filter(item => item.id !== id));
      }
  };

  // --- RENDER HELPERS ---

  const renderSectionHeader = (icon: React.ReactNode, title: string) => (
    <div className="flex items-center gap-2 mb-4 pb-2 border-b border-gray-100">
