  // 2. Define Visual Style Keywords
  let backgroundVisuals = "";
  let forbiddenVisuals = "Messy cluttered text, distorted faces, low resolution.";

  if (isTech) {
      backgroundVisuals = `
      **THEME: HIGH-TECH & AI**
      - **Background Elements:** 3D Microchips, Glowing Circuit Board Traces, Fiber Optic data streams, Metallic textures, Abstract nodes connecting.
      - **Hero Object (Optional):** A sleek, modern Humanoid Robot hand or silhouette, or a floating 3D Processor Chip.
      - **NEGATIVE PROMPT (FORBIDDEN):** DO NOT USE HUMAN BRAINS. DO NOT USE BIOLOGICAL ANATOMY. DO NOT USE OLD-SCHOOL GEARS.
      - **Color Vibe:** Neon Blue, Cyberpunk Cyan, Deep Navy, White accents.
      `;
  } else {
      backgroundVisuals = `
      **THEME: CORPORATE PROFESSIONAL**
      - **Background Elements:** Abstract geometric shapes, fluid gradients, glassmorphism, clean architectural lines.
      - **Vibe:** Trustworthy, Clean, Premium.
      `;
  }

  // 3. Construct the "Senior Designer" Prompt
  let prompt = `
  You are a WORLD-CLASS SENIOR GRAPHIC DESIGNER. Your task is to COMPOSITE a professional event poster.

  **DESIGN PRINCIPLES (STRICT):**
  1. **Visual Hierarchy:** Event Title is the King. Speaker is the Queen. Details are the Court.
  2. **Composition:** Use a balanced, grid-based layout. Ensure wide margins (safety zones) around the edges.
  3. **White Space:** Do not clutter. Let the design breathe.
  4. **Text:** ALL TEXT MUST BE IN VIETNAMESE. Font must be Bold, Sans-Serif, Professional.

  ${backgroundVisuals}

  **NEGATIVE PROMPTS (WHAT TO AVOID):**
  - ${forbiddenVisuals}
  - Do NOT draw the MISA logo by hand. You MUST use the provided logo image.
  - Do NOT change the face of the speaker.
  `;

  // --- BACKGROUND ---
  if (formData.useUploadedBackground && formData.selectedBackground) {
      if (formData.selectedBackground.startsWith('data:image')) {
          parts.push(base64ToPart(formData.selectedBackground));
          prompt += `\n**BACKGROUND SOURCE:** Use Image ${parts.length} as the background base. Layer content on top.`;
      }
  } else {
      prompt += `\n**BACKGROUND GENERATION:** Create a background based on the Theme defined above.`;
  }

  prompt += `\n\n**CONTENT LAYOUT INSTRUCTIONS:**`;

  // --- HEADER SECTION ---
  // Logos
  const misaLogoPart = await getDefaultMisaLogoPart();
  let misaLogoRef = "";
  if (misaLogoPart) {
      parts.push(misaLogoPart);
      misaLogoRef = `Image ${parts.length}`;
  }

  if (formData.useBrandLogo) {
      // Custom Logos
      if (misaLogoRef) prompt += `\n- **Logo 1 (Organizer):** Place ${misaLogoRef} at TOP LEFT on a clean white pill/box background.`;

      if (formData.organizerLogo) {
          parts.push(await fileToPart(formData.organizerLogo));
          prompt += `\n- **Logo 2 (Co-Org):** Place Image ${parts.length} next to Logo 1.`;
      }
      if (formData.productLogo) {
          parts.push(await fileToPart(formData.productLogo));
          prompt += `\n- **Logo 3 (Product):** Place Image ${parts.length} at TOP RIGHT.`;
      }
  } else {
      // Default MISA
      if (misaLogoRef) {
          prompt += `\n- **PRIMARY LOGO:** Place ${misaLogoRef} prominently at the **TOP CENTER** (or Top Left). 
          **CRITICAL:** The logo must be placed inside a **SOLID WHITE RECTANGLE** to ensure readability against the complex background. Do not blend it multiply.`;
      }
  }

  // Event Title & Type
  prompt += `
  \n**HEADLINE SECTION (Top Half):**
  - **Overline (Small):** "${formData.eventType}"
  - **MAIN TITLE (HUGE):** "${formData.eventName.toUpperCase()}"
    - **Effect:** 3D Metallic or Glossy Text effect. High contrast.
    - **Position:** Center or Center-Left alignment.
  `;

  // Time & Location
  const dateTime = `${formData.time} | ${formData.date}`;
  prompt += `\n- **Sub-headline:** "${dateTime}" (Clear, bold text).`;

  if (formData.eventFormat === 'online') {
      prompt += `\n- **Location:** "Hình thức: ${formData.onlinePlatform}" (Add a small Camera/Wifi icon).`;
  } else {
      prompt += `\n- **Location:** "${formData.offlineAddress}" (Add a Map Pin icon).`;
  }

  // --- SPEAKER SECTION (THE HERO) ---
  const validSpeakers = formData.speakers.filter(s => s.name.trim() !== "");

  if (validSpeakers.length > 0) {
      prompt += `
      \n**SPEAKER SECTION (The "Hero" Visual):**
      - **Layout:** Arrange speaker(s) in the lower half.
      - **Style:** Professional Portrait.
      `;

      for (let i = 0; i < validSpeakers.length; i++) {
        const speaker = validSpeakers[i];
        if (speaker.image) {
          parts.push(await fileToPart(speaker.image));
          prompt += `
          \n**SPEAKER ${i + 1} (Reference: Image ${parts.length}):**
          - **IDENTITY LOCK:** This is a real person. **YOU MUST PRESERVE THEIR FACE EXACTLY.** Do not generate a random AI person.
          - **COMPOSITION:** Cut out the person from their background. Place them **LARGE** in the design.
          - **SCALE:** The person should occupy at least **40-50% of the poster height**. They should look impressive and authoritative.
          - **Info Box:** Next to or below the person, add a sleek text box containing:
            - NAME: "${speaker.name}" (Bold, Large)
            - TITLE: "${speaker.title}"
            - COMPANY: "${speaker.company}"
          `;

          if (speaker.editPrompt) {
              prompt += `\n- **Edit Request:** Use the face from Image ${parts.length}, but change body/clothing to: "${speaker.editPrompt}". Keep the head-to-body ratio realistic.`;
          }
        }
      }
  }

  // --- AGENDA & FOOTER ---
  if (formData.agenda.length > 0) {
      prompt += `\n- **Agenda (Optional Side Column):** If space permits, list: ${formData.agenda.map(a => `${a.time}-${a.activity}`).join('; ')}.`;
  }

  // Footer Contact
  const contact = [formData.contactName, formData.contactPhone].filter(Boolean).join(' - ');
  if (contact) {
      prompt += `\n- **Footer Bar:** Create a clean bar at the very bottom containing: "Hotline: ${contact}".`;
  }

  // QR Code
  if (formData.includeQrCode) {
      if (formData.qrCodeImage) {
          parts.push(await fileToPart(formData.qrCodeImage));
          prompt += `\n- **QR Code:** Place Image ${parts.length} at Bottom Right. Add text "${formData.qrCta}".`;
      } else {
          prompt += `\n- **QR Code:** Leave a White Square Box at Bottom Right for QR Code.`;
      }
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // High quality model is mandatory for text/layout
      contents: { parts: parts },
      config: {
        imageConfig: {
            aspectRatio: formData.aspectRatio,
            imageSize: '2K'
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image generated.");
  } catch (error) {
    console.error("Poster Generation Failed", error);
    const msg = (error as any).message || "Unknown Error";
    throw new Error(`Poster Generation Failed: ${msg}`);
  }
};
